func init() {
	for i := range Catalog {
		if a, ok := abouts[Catalog[i].Key]; ok {
			Catalog[i].Description, Catalog[i].Site = a.text, a.site
		}
		Catalog[i].Logo = LogoURL(Catalog[i]) != ""
	}
}
